use low_latency_lab_benchmarks::bybit_l2_dense_ladder::DenseLadderBook;
use low_latency_lab_benchmarks::bybit_l2_order_book::{Change, Level, OrderBook, Price, Side};
use low_latency_lab_benchmarks::bybit_l2_ordered_map::OrderedMapBook;
use std::time::Instant;
const EVENTS: usize = 100_000; const WARMUPS: usize = 10; const SAMPLES: usize = 200;
fn levels(side: Side, n: usize, gap: Price) -> Vec<Level> {(0..n).map(|i| Level {price: if side == Side::Bid {2_000_000-i as u64*gap} else {2_000_001+i as u64*gap}, quantity:100+i as u64}).collect()}
fn trace(workload:&str,b:&[Level],a:&[Level],gap:Price)->Vec<Change>{(0..EVENTS).map(|i|{let side=if(i/2)%2==1{Side::Bid}else{Side::Ask};let idx=((i/2)/2)%b.len();let base=if side==Side::Bid{b[idx].price}else{a[idx].price};let round=(i/2)/(2*b.len());let active=base+if round%2==1{gap/2}else{0};let other=base+if round%2==1{0}else{gap/2};if workload=="replace"{Change{side,price:base,quantity:100+i as u64%97}}else if i%2==0{Change{side,price:active,quantity:0}}else{Change{side,price:other,quantity:100+i as u64%97}}}).collect()}
fn main(){let variant=std::env::args().nth(1).expect("variant");let workload=std::env::args().nth(2).expect("workload");let n=if workload=="wide"{1000}else{50};let gap=if workload=="wide"{1000}else{2};let b=levels(Side::Bid,n,gap);let a=levels(Side::Ask,n,gap);let e=trace(&workload,&b,&a,gap);let one=||match variant.as_str(){"vector"=>{let mut x=OrderBook::new(n);assert!(x.apply_snapshot(1,&b,&a));let t=Instant::now();for(i,c)in e.iter().enumerate(){assert!(x.apply_delta(i as u64+2,&[*c]));}let r=t.elapsed().as_nanos()as f64/EVENTS as f64;std::hint::black_box(x.best_bid());r},"dense"=>{let mut x=DenseLadderBook::new(0,3_000_000);assert!(x.apply_snapshot(1,&b,&a));let t=Instant::now();for(i,c)in e.iter().enumerate(){assert!(x.apply_delta(i as u64+2,&[*c]));}let r=t.elapsed().as_nanos()as f64/EVENTS as f64;std::hint::black_box(x.best_bid());r},"map"=>{let mut x=OrderedMapBook::new();assert!(x.apply_snapshot(1,&b,&a));let t=Instant::now();for(i,c)in e.iter().enumerate(){assert!(x.apply_delta(i as u64+2,&[*c]));}let r=t.elapsed().as_nanos()as f64/EVENTS as f64;std::hint::black_box(x.best_bid());r},_=>panic!("variant")};for _ in 0..WARMUPS{one();}let mut s:Vec<_>=(0..SAMPLES).map(|_|one()).collect();let mean=s.iter().sum::<f64>()/SAMPLES as f64;s.sort_by(f64::total_cmp);println!("variant={variant} workload={workload} levels={n} events={EVENTS} samples={SAMPLES} p50_ns={} p95_ns={} p99_ns={} p995_ns={} max_ns={} mean_ns={mean}",s[99],s[189],s[197],s[198],s[199]);}
